SELECT s.trading_date,r.fetched_at,jsonb_build_object('fields',p->'scheduled_plan'->'query'->'fields','filters',p->'scheduled_plan'->'query'->'filters','timezone',p->'scheduled_plan'->'query'->'query_timezone') AS scheduled_query FROM canonical_daily_sales s JOIN raw_record r ON r.id=s.raw_record_id CROSS JOIN LATERAL (SELECT convert_from(r.payload_bytes,'UTF8')::jsonb p) raw WHERE s.superseded_at IS NULL AND s.source_system='LIGHTSPEED' AND s.trading_date BETWEEN '2026-10-26' AND '2026-11-01' ORDER BY s.trading_date;
SELECT count(*) lines,count(sale_closed_ten_minute_time) closed_times,count(site_number) sites,min(trading_date) first_date,max(trading_date) last_date FROM resolved_sale_line WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01';
SELECT trading_date,sum((adjustment->>'finalExTax')::numeric) cashout_net,sum(amount) cashout_gross,count(*) lines FROM resolved_sale_line WHERE lower(item_name)='cash out' AND trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1 ORDER BY 1;
